import csv

def load_records(path):
    records = []
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            records.append({
                'name': row['name'],
                'value': int(row['value'])
            })
    return records

def summarize(records):
    total = sum(r['value'] for r in records)
    count = len(records)
    by_name = {}
    for r in records:
        by_name[r['name']] = by_name.get(r['name'], 0) + r['value']
    return {
        'count': count,
        'total': total,
        'by_name': by_name
    }

