{"function": {"arguments": {"content": "const fs = require('fs');

const events = JSON.parse(fs.readFileSync('events.json', 'utf8'));

const seen = new Map();
const ledger = [];

for (const event of events) {
  const id = event.id;
  if (!seen.has(id)) {
    seen.set(id, { count: 0, total_amount: 0 });
  }
  const entry = seen.get(id);
  entry.count += 1;
  entry.total_amount += event.amount;
}

for (const entry of seen.values()) {
  ledger.push({
    id: entry.id,
    count: entry.count,
    total_amount: entry.total_amount
  });
}

const output = JSON.stringify(ledger, null, 2);
fs.writeFileSync('ledger.json', output, 'utf8');

console.log('Ledger written to ledger.json');
